'use strict';

const path = require('node:path');
const semver = require('semver');
const { parsePomXml, getPomPropertyValue } = require('../util/pom');
const { javaCdsMajorFor, rangeSatisfiesTarget } = require('../constants');

function majorFromRange(range) {
  const openMatch = range.match(/^>=?\s*(\d+)/);
  if (openMatch) return parseInt(openMatch[1], 10);
  try {
    const min = semver.minVersion(range);
    if (min && min.major > 0) return min.major;
  } catch { /* fall through */ }
  return 1;
}

function resolveProjectMajor(ctx, cds) {
  if (ctx.project.isNode) {
    const lockPath = path.join(cds.root, 'package-lock.json');
    if (cds.utils.exists(lockPath)) {
      try {
        const lock = JSON.parse(cds.utils.fs.readFileSync(lockPath, 'utf8'));
        for (const depName of ['@sap/cds', '@sap/cds-dk']) {
          const entry = lock.packages?.[`node_modules/${depName}`] || lock.dependencies?.[depName];
          if (entry?.version) return semver.major(entry.version);
        }
      } catch { /* fall through */ }
    }
    // Skip permissive ranges (`*`, `latest`, `>=N`) — they're not evidence of a
    // specific project major. Fall back to the target only if every declared
    // range is permissive.
    const target = ctx.target;
    for (const pkgPath of ctx.project.packageJsonFiles) {
      let pkg;
      try { pkg = JSON.parse(cds.utils.fs.readFileSync(pkgPath, 'utf8')); } catch { continue; }
      const deps = { ...pkg.dependencies, ...pkg.devDependencies };
      for (const name of ['@sap/cds', '@sap/cds-dk']) {
        const range = deps[name];
        if (!range) continue;
        if (target != null && rangeSatisfiesTarget(range, target)) continue;
        return majorFromRange(range);
      }
    }
    // Everything was permissive — treat as being on target.
    if (target != null) return target;
  }
  if (ctx.project.isJava) {
    for (const pomPath of ctx.project.pomXmlFiles) {
      let pom;
      try { pom = parsePomXml(pomPath); } catch { continue; }
      const raw = getPomPropertyValue(pom, 'cds.services.version');
      if (!raw) continue;
      const m = raw.match(/^(\d+)/);
      if (m) return javaCdsMajorFor(parseInt(m[1], 10));
    }
  }
  return null;
}

module.exports = { resolveProjectMajor, majorFromRange };
